"""Link document atoms and historical sharing identity checks after s0_0734."""

SCHEMA_SQL = ("\nCREATE FUNCTION m3_evidence_proposal_identity_tokens(t uuid,c uuid,pid uuid) RETURNS SETOF text\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n WITH registered_data AS (\n  SELECT p.source_refs||p.context_refs data FROM proposals p WHERE p.tenant_id=t AND p.category_id=c AND p.id=pid\n  UNION ALL SELECT v.source_refs FROM proposal_item_versions v WHERE v.tenant_id=t AND v.category_id=c AND v.proposal_id=pid\n  UNION ALL SELECT v.changed_items FROM proposal_revisions v WHERE v.tenant_id=t AND v.category_id=c AND v.proposal_id=pid\n  UNION ALL SELECT jsonb_build_array(s.frozen_document,s.context_refs) FROM proposal_submissions s\n   WHERE s.tenant_id=t AND s.category_id=c AND s.proposal_id=pid\n  UNION ALL SELECT jsonb_build_object('type',l.evidence_type,'id',l.evidence_id) FROM evidence_links l\n   JOIN proposal_items i ON i.tenant_id=l.tenant_id AND i.category_id=l.category_id AND i.id=l.target_id\n   WHERE l.tenant_id=t AND l.category_id=c AND l.target_type='proposal_item' AND i.proposal_id=pid\n ), referenced_claims AS (\n  SELECT unnest(m3_evidence_reference_ids(data,'claim')) id FROM registered_data\n ), artifact_ids AS (\n  SELECT ps.source_id id FROM proposal_sources ps WHERE ps.tenant_id=t AND ps.category_id=c AND ps.proposal_id=pid AND ps.source_type='original'\n  UNION SELECT unnest(m3_evidence_reference_ids(data,'artifact')||m3_evidence_reference_ids(data,'original')) FROM registered_data\n  UNION SELECT k.artifact_id FROM claims k JOIN referenced_claims ref ON ref.id=k.id\n   WHERE k.tenant_id=t AND k.category_id=c AND k.source_kind='artifact'\n  UNION SELECT (source->>'artifact_id')::uuid FROM claims k\n   JOIN agent_runs ar ON ar.tenant_id=k.tenant_id AND ar.category_id=k.category_id AND ar.id=k.run_id AND ar.proposal_id=k.proposal_id\n    AND ar.requester_id=k.human_owner_id AND ar.writer_id=k.writer_id\n   CROSS JOIN LATERAL jsonb_array_elements(ar.read_sources) source\n   WHERE k.tenant_id=t AND k.category_id=c AND k.proposal_id=pid AND k.privacy='private' AND ar.private_context\n ), registered_originals AS (\n  SELECT a.id artifact_id,o.id original_id,o.filename FROM artifact_ids ref\n   JOIN artifact_versions a ON a.tenant_id=t AND a.category_id=c AND a.id=ref.id\n   JOIN uploaded_originals o ON o.tenant_id=a.tenant_id AND o.category_id=a.category_id AND o.id=a.original_id\n )\n SELECT lower(filename) FROM registered_originals UNION SELECT artifact_id::text FROM registered_originals\n UNION SELECT original_id::text FROM registered_originals\n$$;\n", 'REVOKE ALL ON FUNCTION m3_evidence_proposal_identity_tokens(uuid,uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'CREATE OR REPLACE FUNCTION public.m3_atom_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'pg_catalog\', \'public\', \'pg_temp\'\nAS $function$\nDECLARE r action_receipts; p proposals; sub proposal_submissions; d proposal_decisions; frozen jsonb;\nBEGIN\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.proposal_id;\n IF TG_TABLE_NAME=\'proposal_revisions\' AND r.operation=\'evidence.link.create\' THEN\n  IF r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS NOT NULL\n   OR r.subject_type IS DISTINCT FROM \'evidence_link\' OR r.subject_revision IS DISTINCT FROM 1\n   OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM scope_requester()\n   OR r.run_id IS NOT NULL OR NEW.actor_id IS DISTINCT FROM r.actor_id OR NEW.run_id IS DISTINCT FROM r.agent_run_id\n   OR p.category_id IS DISTINCT FROM NEW.category_id OR p.owner_id IS DISTINCT FROM r.requester_id\n   OR p.status NOT IN (\'draft\',\'returned\') OR p.revision IS DISTINCT FROM NEW.revision\n   OR NEW.changed_items IS DISTINCT FROM \'[]\'::jsonb\n   OR NOT EXISTS(SELECT 1 FROM proposal_revisions prior WHERE prior.tenant_id=NEW.tenant_id\n    AND prior.category_id=NEW.category_id AND prior.proposal_id=NEW.proposal_id AND prior.revision=NEW.revision-1)\n   OR NOT EXISTS(SELECT 1 FROM evidence_links link JOIN proposal_items item ON item.tenant_id=link.tenant_id\n    AND item.category_id=link.category_id AND item.id=link.target_id\n    JOIN action_receipts receipt ON receipt.tenant_id=link.tenant_id AND receipt.id=link.receipt_id\n    JOIN proposal_revisions revision ON revision.tenant_id=link.tenant_id AND revision.receipt_id=receipt.id\n    JOIN proposals current_proposal ON current_proposal.tenant_id=item.tenant_id AND current_proposal.id=item.proposal_id\n    WHERE link.tenant_id=NEW.tenant_id AND link.category_id=NEW.category_id AND link.id=r.subject_id\n     AND link.receipt_id=r.id AND link.target_type=\'proposal_item\' AND link.reverted_by_receipt_id IS NULL\n     AND link.run_id IS NOT DISTINCT FROM r.agent_run_id AND item.proposal_id=NEW.proposal_id\n     AND NOT item.removed AND item.current_version=link.target_version AND revision.id=NEW.id\n     AND revision.proposal_id=NEW.proposal_id AND revision.revision=NEW.revision\n     AND link.xmin=receipt.xmin AND revision.xmin=receipt.xmin AND current_proposal.xmin=receipt.xmin\n     AND r.result->>\'link_id\'=link.id::text\n     AND r.result->\'target\'=jsonb_build_object(\'type\',link.target_type,\'id\',link.target_id,\'version\',link.target_version))\n   OR (SELECT count(*) FROM proposal_revisions revision WHERE revision.tenant_id=NEW.tenant_id AND revision.receipt_id=r.id)<>1\n   OR p.private_source_count<>(SELECT count(*) FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=p.id AND ps.privacy=\'private\')\n   OR p.effective_visibility IS DISTINCT FROM (CASE WHEN p.private_source_count>0 THEN \'private\' ELSE p.visibility END)\n   OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id)\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id)\n     UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=p.id\n      EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,p.id))) THEN\n   RAISE EXCEPTION \'evidence link proposal receipt or projection mismatch\' USING ERRCODE=\'23514\'; END IF;\n  RETURN NULL;\n END IF;\n IF r.category_id<>NEW.category_id OR r.subject_type<>\'proposal\' OR r.subject_id<>NEW.proposal_id\n  OR r.actor_id<>scope_actor() OR r.requester_id<>scope_requester() OR r.run_id IS NOT NULL\n  OR (r.agent_run_id IS NOT NULL AND r.operation<>\'proposal.item.patch\')\n  THEN RAISE EXCEPTION \'M3 common receipt binding\'; END IF;\n IF TG_TABLE_NAME=\'proposal_submissions\' THEN\n  IF r.operation<>\'proposal.g0.submit\' OR r.actor_id<>NEW.owner_id\n   OR NEW.owner_id<>p.owner_id OR NEW.owner_id=NEW.reviewer_id THEN\n   RAISE EXCEPTION \'M3 independent submission atom\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_decisions\' THEN\n  SELECT * INTO STRICT sub FROM proposal_submissions WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id;\n  IF r.operation<>\'proposal.g0.decide\' OR r.actor_id<>NEW.decided_by\n   OR p.status<>NEW.outcome OR p.current_submission_id<>NEW.submission_id\n   OR p.owner_id<>NEW.owner_id OR NEW.review_digest<>sub.document_digest\n   OR NEW.decided_by<>sub.reviewer_id THEN RAISE EXCEPTION \'M3 named decision atom\'; END IF;\n  IF NEW.outcome=\'approved\' AND (\n   NOT EXISTS(SELECT 1 FROM definition_revisions def WHERE def.tenant_id=NEW.tenant_id\n    AND def.id=NEW.created_definition_id AND def.product_id=NEW.created_product_id\n    AND def.sealed AND def.revision=1 AND def.g0_decision_id=NEW.id)\n   OR NOT EXISTS(SELECT 1 FROM projects project WHERE project.tenant_id=NEW.tenant_id\n    AND project.id=NEW.created_project_id AND project.product_id=NEW.created_product_id\n    AND project.g0_decision_id=NEW.id AND project.owner_id=NEW.project_owner_id)\n   OR NOT EXISTS(SELECT 1 FROM project_product_links link WHERE link.tenant_id=NEW.tenant_id\n    AND link.project_id=NEW.created_project_id AND link.product_id=NEW.created_product_id\n    AND link.definition_id=NEW.created_definition_id AND link.definition_revision=1)\n   OR (SELECT count(*) FROM project_open_items oi WHERE oi.tenant_id=NEW.tenant_id\n    AND oi.g0_decision_id=NEW.id)<>jsonb_array_length(NEW.dispositions)) THEN\n   RAISE EXCEPTION \'M3 G0 results must commit together\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_item_versions\' THEN\n  IF r.operation=\'proposal.g0.decide\' THEN\n   SELECT * INTO STRICT d FROM proposal_decisions WHERE tenant_id=NEW.tenant_id AND receipt_id=r.id;\n   SELECT item INTO STRICT frozen FROM proposal_submissions ps,\n    LATERAL jsonb_array_elements(ps.frozen_document->\'items\') item\n    WHERE ps.tenant_id=NEW.tenant_id AND ps.id=d.submission_id AND item->>\'item_id\'=NEW.item_id::text;\n   IF d.outcome<>\'approved\' OR NEW.kind<>\'question\' OR NEW.removed\n    OR NEW.version<>(frozen->>\'version\')::int+1\n    OR NEW.content IS DISTINCT FROM ((frozen->\'content\')||\'{"status":"carried"}\'::jsonb)\n    OR NEW.origin IS DISTINCT FROM frozen->>\'origin\'\n    OR NEW.source_refs IS DISTINCT FROM frozen->\'source_refs\'\n    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d.dispositions) disp\n     WHERE disp->>\'subject_type\'=\'question\' AND disp->>\'subject_id\'=NEW.item_id::text)\n    THEN RAISE EXCEPTION \'M3 only decided questions may be carried\'; END IF;\n  END IF;\n  IF r.operation NOT IN (\'proposal.create\',\'proposal.item.patch\',\'proposal.question.create\',\'proposal.g0.decide\')\n   OR NOT coalesce((\n    (NEW.origin=\'human\' AND NEW.writer_id=r.actor_id AND NEW.run_id IS NULL\n     AND NEW.confirmed_by IS NULL AND NEW.prepared_candidate_id IS NULL AND r.agent_run_id IS NULL)\n    OR (NEW.origin=\'ai_draft\' AND NEW.writer_id=r.actor_id AND NEW.run_id=r.agent_run_id\n     AND NEW.confirmed_by IS NULL AND NEW.prepared_candidate_id IS NULL\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id\n      AND ar.category_id=NEW.category_id AND ar.requester_id=r.requester_id AND ar.writer_id=r.actor_id\n      AND ar.proposal_id=NEW.proposal_id AND ar.reverted_at IS NULL AND ar.state<>\'cancelled\')\n     AND EXISTS(SELECT 1 FROM agent_tool_calls ac WHERE ac.tenant_id=NEW.tenant_id\n      AND ac.run_id=NEW.run_id AND ac.receipt_id=r.id AND ac.state=\'completed\'\n      AND ac.execution_binding->>\'operation\'=r.operation)\n     AND NOT EXISTS(SELECT 1 FROM proposal_item_versions prior WHERE prior.tenant_id=NEW.tenant_id\n      AND prior.item_id=NEW.item_id AND prior.version=NEW.version-1\n      AND (prior.origin=\'human\' OR prior.confirmed_by IS NOT NULL)))\n    OR (NEW.origin=\'ai_draft\' AND r.agent_run_id IS NULL AND NEW.confirmed_by=r.actor_id\n     AND EXISTS(SELECT 1 FROM proposal_prepared_candidates pc WHERE pc.tenant_id=NEW.tenant_id\n      AND pc.id=NEW.prepared_candidate_id AND pc.category_id=NEW.category_id\n      AND pc.requester_id=r.requester_id AND pc.writer_id=NEW.writer_id AND pc.run_id=NEW.run_id\n      AND pc.operation=r.operation))\n    OR (r.operation=\'proposal.g0.decide\' AND NEW.origin=\'ai_draft\'\n     AND NEW.origin=frozen->>\'origin\' AND NEW.writer_id=(frozen->>\'writer_id\')::uuid\n     AND NEW.run_id=(frozen->>\'run_id\')::uuid AND NEW.confirmed_by=r.actor_id\n     AND NEW.prepared_candidate_id IS NULL)),false)\n  THEN RAISE EXCEPTION \'M3 version provenance\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_revisions\' THEN\n  IF NEW.actor_id<>r.actor_id OR NEW.run_id IS DISTINCT FROM r.agent_run_id\n   OR NEW.revision<>r.subject_revision THEN\n   RAISE EXCEPTION \'M3 document receipt revision\'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n', "CREATE OR REPLACE FUNCTION public.m3_evidence_share_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; cp confirmations; payload jsonb; k claims; root jsonb; material text; token text; rx xid; cx xid;\nBEGIN\n -- An evidence association advances only the document revision and source\n -- projection. Its receipt is checked by m3_atom_guard and its own Link atom.\n IF NEW.revision<>OLD.revision AND EXISTS(SELECT 1 FROM proposal_revisions pv\n  JOIN action_receipts receipt ON receipt.tenant_id=pv.tenant_id AND receipt.id=pv.receipt_id\n  WHERE pv.tenant_id=NEW.tenant_id AND pv.category_id=NEW.category_id AND pv.proposal_id=NEW.id\n   AND pv.revision=NEW.revision AND receipt.operation='evidence.link.create') THEN\n  IF NEW.revision<>OLD.revision+1\n   OR (to_jsonb(NEW)-ARRAY['revision','private_source_count','effective_visibility']) IS DISTINCT FROM\n      (to_jsonb(OLD)-ARRAY['revision','private_source_count','effective_visibility']) THEN\n   RAISE EXCEPTION 'evidence link cannot change proposal content' USING ERRCODE='23514'; END IF;\n  RETURN NULL;\n END IF;\n IF NEW.visibility IS NOT DISTINCT FROM OLD.visibility AND NEW.revision=OLD.revision THEN RETURN NULL; END IF;\n IF NEW.visibility IS NOT DISTINCT FROM OLD.visibility AND NOT EXISTS(\n  SELECT 1 FROM proposal_revisions pv JOIN action_receipts rr ON rr.tenant_id=pv.tenant_id AND rr.id=pv.receipt_id\n  WHERE pv.tenant_id=NEW.tenant_id AND pv.proposal_id=NEW.id AND pv.revision=NEW.revision AND rr.operation='proposal.share') THEN RETURN NULL; END IF;\n IF NEW.visibility NOT IN ('category','audience') OR NEW.effective_visibility<>NEW.visibility\n  OR NEW.private_source_count<>0 OR NEW.owner_id IS DISTINCT FROM scope_actor() OR scope_actor()<>scope_requester() THEN\n  RAISE EXCEPTION 'proposal share requires owner' USING ERRCODE='23514'; END IF;\n SELECT rr.* INTO STRICT r FROM action_receipts rr JOIN proposal_revisions rev ON rev.tenant_id=rr.tenant_id AND rev.receipt_id=rr.id\n  WHERE rev.tenant_id=NEW.tenant_id AND rev.proposal_id=NEW.id AND rev.revision=NEW.revision;\n SELECT * INTO STRICT cp FROM confirmations WHERE tenant_id=NEW.tenant_id AND id=r.confirmation_id;\n payload=cp.snapshot->'payload';\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n SELECT xmin INTO cx FROM confirmations WHERE tenant_id=NEW.tenant_id AND id=cp.id;\n IF rx IS DISTINCT FROM cx OR rx IS DISTINCT FROM (SELECT xmin FROM proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n  OR cp.consumed IS DISTINCT FROM true OR cp.operation<>'proposal.share' OR cp.subject_type<>'proposal'\n  OR cp.subject_id<>NEW.id OR cp.revision<>OLD.revision OR cp.actor_id<>NEW.owner_id OR cp.product_id IS NOT NULL\n  OR cp.category_id<>NEW.category_id OR r.operation<>cp.operation OR r.subject_id<>NEW.id OR r.subject_type<>'proposal'\n  OR r.subject_revision<>NEW.revision OR r.actor_id<>NEW.owner_id OR r.requester_id<>NEW.owner_id\n  OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL OR r.product_id IS NOT NULL OR r.category_id<>NEW.category_id\n  OR (payload->>'proposal_id')::uuid IS DISTINCT FROM NEW.id OR (payload->>'expected_revision')::integer IS DISTINCT FROM OLD.revision\n  OR payload->>'visibility' IS DISTINCT FROM NEW.visibility OR jsonb_typeof(payload->'audience_ids') IS DISTINCT FROM 'array' THEN\n  RAISE EXCEPTION 'proposal share confirmation mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id) roots WHERE roots.privacy='private')\n  OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id)\n    EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=NEW.id)\n   UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=NEW.id\n    EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id))) THEN\n  RAISE EXCEPTION 'proposal share source projection mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'audience_ids') person WHERE NOT EXISTS(\n  SELECT 1 FROM object_audiences a JOIN principals pr ON pr.tenant_id=a.tenant_id AND pr.id=a.principal_id\n   JOIN grants g ON g.tenant_id=a.tenant_id AND g.category_id=a.category_id AND g.principal_id=a.principal_id\n   WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id AND a.object_type='proposals' AND a.subject_id=NEW.id\n    AND a.principal_id=person::uuid AND a.owner_id=NEW.owner_id AND pr.active AND pr.kind='human'\n    AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp()))) THEN\n  RAISE EXCEPTION 'proposal share audience mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM object_audiences a WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id\n   AND a.object_type='proposals' AND a.subject_id=NEW.id AND NOT EXISTS(\n    SELECT 1 FROM jsonb_array_elements_text(payload->'audience_ids') v WHERE v::uuid=a.principal_id)\n   AND NOT EXISTS(SELECT 1 FROM proposal_submissions sub WHERE sub.tenant_id=NEW.tenant_id\n    AND sub.id=NEW.current_submission_id AND sub.reviewer_id=a.principal_id))\n  OR EXISTS(SELECT 1 FROM proposal_submissions sub WHERE sub.tenant_id=NEW.tenant_id AND sub.id=NEW.current_submission_id\n   AND NOT EXISTS(SELECT 1 FROM object_audiences a WHERE a.tenant_id=NEW.tenant_id AND a.object_type='proposals'\n    AND a.subject_id=NEW.id AND a.principal_id=sub.reviewer_id)) THEN\n  RAISE EXCEPTION 'proposal share final audience set mismatch' USING ERRCODE='23514'; END IF;\n FOR k IN SELECT * FROM claims WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND proposal_id=NEW.id\n  AND status='active' AND privacy='private' ORDER BY id FOR UPDATE LOOP\n  root=m3_evidence_root(NEW.tenant_id,NEW.category_id,k.source_kind,coalesce(k.artifact_id,k.snapshot_id),k.source_revision);\n  IF (root->>'private')::boolean OR (payload->>'deidentified_confirmed')::boolean IS DISTINCT FROM true THEN\n   RAISE EXCEPTION 'private claim sharing needs deidentification' USING ERRCODE='23514'; END IF;\n  material=lower(jsonb_build_object('content',k.content,'quote',k.quote,'statement',k.statement)::text);\n  IF material ~ '(https?://|www\\.)' THEN RAISE EXCEPTION 'claim identity link not removed' USING ERRCODE='23514'; END IF;\n  FOR token IN SELECT lower(value) FROM jsonb_array_elements_text(NEW.customer_identities) value\n   UNION SELECT lower(o.filename) FROM proposal_sources ps JOIN artifact_versions a ON a.tenant_id=ps.tenant_id AND a.id=ps.source_id\n    JOIN uploaded_originals o ON o.tenant_id=a.tenant_id AND o.id=a.original_id\n    WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=NEW.id AND ps.source_type='original'\n   UNION SELECT identity_token FROM m3_evidence_proposal_identity_tokens(NEW.tenant_id,NEW.category_id,NEW.id) identity_token\n   UNION SELECT NEW.id::text\n   UNION SELECT ps.source_id::text FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=NEW.id LOOP\n   IF token<>'' AND position(token IN material)>0 THEN RAISE EXCEPTION 'claim identity not removed' USING ERRCODE='23514'; END IF;\n  END LOOP;\n END LOOP;\n RETURN NULL;\nEND $function$\n")

DOWNGRADE_SQL = ("CREATE OR REPLACE FUNCTION public.m3_evidence_share_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; cp confirmations; payload jsonb; k claims; root jsonb; material text; token text; rx xid; cx xid;\nBEGIN\n IF NEW.visibility IS NOT DISTINCT FROM OLD.visibility AND NEW.revision=OLD.revision THEN RETURN NULL; END IF;\n IF NEW.visibility IS NOT DISTINCT FROM OLD.visibility AND NOT EXISTS(\n  SELECT 1 FROM proposal_revisions pv JOIN action_receipts rr ON rr.tenant_id=pv.tenant_id AND rr.id=pv.receipt_id\n  WHERE pv.tenant_id=NEW.tenant_id AND pv.proposal_id=NEW.id AND pv.revision=NEW.revision AND rr.operation='proposal.share') THEN RETURN NULL; END IF;\n IF NEW.visibility NOT IN ('category','audience') OR NEW.effective_visibility<>NEW.visibility\n  OR NEW.private_source_count<>0 OR NEW.owner_id IS DISTINCT FROM scope_actor() OR scope_actor()<>scope_requester() THEN\n  RAISE EXCEPTION 'proposal share requires owner' USING ERRCODE='23514'; END IF;\n SELECT rr.* INTO STRICT r FROM action_receipts rr JOIN proposal_revisions rev ON rev.tenant_id=rr.tenant_id AND rev.receipt_id=rr.id\n  WHERE rev.tenant_id=NEW.tenant_id AND rev.proposal_id=NEW.id AND rev.revision=NEW.revision;\n SELECT * INTO STRICT cp FROM confirmations WHERE tenant_id=NEW.tenant_id AND id=r.confirmation_id;\n payload=cp.snapshot->'payload';\n SELECT xmin INTO rx FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=r.id;\n SELECT xmin INTO cx FROM confirmations WHERE tenant_id=NEW.tenant_id AND id=cp.id;\n IF rx IS DISTINCT FROM cx OR rx IS DISTINCT FROM (SELECT xmin FROM proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.id)\n  OR cp.consumed IS DISTINCT FROM true OR cp.operation<>'proposal.share' OR cp.subject_type<>'proposal'\n  OR cp.subject_id<>NEW.id OR cp.revision<>OLD.revision OR cp.actor_id<>NEW.owner_id OR cp.product_id IS NOT NULL\n  OR cp.category_id<>NEW.category_id OR r.operation<>cp.operation OR r.subject_id<>NEW.id OR r.subject_type<>'proposal'\n  OR r.subject_revision<>NEW.revision OR r.actor_id<>NEW.owner_id OR r.requester_id<>NEW.owner_id\n  OR r.agent_run_id IS NOT NULL OR r.run_id IS NOT NULL OR r.product_id IS NOT NULL OR r.category_id<>NEW.category_id\n  OR (payload->>'proposal_id')::uuid IS DISTINCT FROM NEW.id OR (payload->>'expected_revision')::integer IS DISTINCT FROM OLD.revision\n  OR payload->>'visibility' IS DISTINCT FROM NEW.visibility OR jsonb_typeof(payload->'audience_ids') IS DISTINCT FROM 'array' THEN\n  RAISE EXCEPTION 'proposal share confirmation mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id) roots WHERE roots.privacy='private')\n  OR EXISTS((SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id)\n    EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=NEW.id)\n   UNION ALL (SELECT source_type,source_id,source_version,privacy,ref_count::bigint FROM proposal_sources WHERE tenant_id=NEW.tenant_id AND proposal_id=NEW.id\n    EXCEPT SELECT source_type,source_id,source_version,privacy,ref_count FROM m3_evidence_proposal_roots(NEW.tenant_id,NEW.category_id,NEW.id))) THEN\n  RAISE EXCEPTION 'proposal share source projection mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'audience_ids') person WHERE NOT EXISTS(\n  SELECT 1 FROM object_audiences a JOIN principals pr ON pr.tenant_id=a.tenant_id AND pr.id=a.principal_id\n   JOIN grants g ON g.tenant_id=a.tenant_id AND g.category_id=a.category_id AND g.principal_id=a.principal_id\n   WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id AND a.object_type='proposals' AND a.subject_id=NEW.id\n    AND a.principal_id=person::uuid AND a.owner_id=NEW.owner_id AND pr.active AND pr.kind='human'\n    AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp()))) THEN\n  RAISE EXCEPTION 'proposal share audience mismatch' USING ERRCODE='23514'; END IF;\n IF EXISTS(SELECT 1 FROM object_audiences a WHERE a.tenant_id=NEW.tenant_id AND a.category_id=NEW.category_id\n   AND a.object_type='proposals' AND a.subject_id=NEW.id AND NOT EXISTS(\n    SELECT 1 FROM jsonb_array_elements_text(payload->'audience_ids') v WHERE v::uuid=a.principal_id)\n   AND NOT EXISTS(SELECT 1 FROM proposal_submissions sub WHERE sub.tenant_id=NEW.tenant_id\n    AND sub.id=NEW.current_submission_id AND sub.reviewer_id=a.principal_id))\n  OR EXISTS(SELECT 1 FROM proposal_submissions sub WHERE sub.tenant_id=NEW.tenant_id AND sub.id=NEW.current_submission_id\n   AND NOT EXISTS(SELECT 1 FROM object_audiences a WHERE a.tenant_id=NEW.tenant_id AND a.object_type='proposals'\n    AND a.subject_id=NEW.id AND a.principal_id=sub.reviewer_id)) THEN\n  RAISE EXCEPTION 'proposal share final audience set mismatch' USING ERRCODE='23514'; END IF;\n FOR k IN SELECT * FROM claims WHERE tenant_id=NEW.tenant_id AND category_id=NEW.category_id AND proposal_id=NEW.id\n  AND status='active' AND privacy='private' ORDER BY id FOR UPDATE LOOP\n  root=m3_evidence_root(NEW.tenant_id,NEW.category_id,k.source_kind,coalesce(k.artifact_id,k.snapshot_id),k.source_revision);\n  IF (root->>'private')::boolean OR (payload->>'deidentified_confirmed')::boolean IS DISTINCT FROM true THEN\n   RAISE EXCEPTION 'private claim sharing needs deidentification' USING ERRCODE='23514'; END IF;\n  material=lower(jsonb_build_object('content',k.content,'quote',k.quote,'statement',k.statement)::text);\n  IF material ~ '(https?://|www\\.)' THEN RAISE EXCEPTION 'claim identity link not removed' USING ERRCODE='23514'; END IF;\n  FOR token IN SELECT lower(value) FROM jsonb_array_elements_text(NEW.customer_identities) value\n   UNION SELECT lower(o.filename) FROM proposal_sources ps JOIN artifact_versions a ON a.tenant_id=ps.tenant_id AND a.id=ps.source_id\n    JOIN uploaded_originals o ON o.tenant_id=a.tenant_id AND o.id=a.original_id\n    WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=NEW.id AND ps.source_type='original'\n   UNION SELECT NEW.id::text\n   UNION SELECT ps.source_id::text FROM proposal_sources ps WHERE ps.tenant_id=NEW.tenant_id AND ps.proposal_id=NEW.id LOOP\n   IF token<>'' AND position(token IN material)>0 THEN RAISE EXCEPTION 'claim identity not removed' USING ERRCODE='23514'; END IF;\n  END LOOP;\n END LOOP;\n RETURN NULL;\nEND $function$\n", 'CREATE OR REPLACE FUNCTION public.m3_atom_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'pg_catalog\', \'public\', \'pg_temp\'\nAS $function$\nDECLARE r action_receipts; p proposals; sub proposal_submissions; d proposal_decisions; frozen jsonb;\nBEGIN\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n SELECT * INTO STRICT p FROM proposals WHERE tenant_id=NEW.tenant_id AND id=NEW.proposal_id;\n IF r.category_id<>NEW.category_id OR r.subject_type<>\'proposal\' OR r.subject_id<>NEW.proposal_id\n  OR r.actor_id<>scope_actor() OR r.requester_id<>scope_requester() OR r.run_id IS NOT NULL\n  OR (r.agent_run_id IS NOT NULL AND r.operation<>\'proposal.item.patch\')\n  THEN RAISE EXCEPTION \'M3 common receipt binding\'; END IF;\n IF TG_TABLE_NAME=\'proposal_submissions\' THEN\n  IF r.operation<>\'proposal.g0.submit\' OR r.actor_id<>NEW.owner_id\n   OR NEW.owner_id<>p.owner_id OR NEW.owner_id=NEW.reviewer_id THEN\n   RAISE EXCEPTION \'M3 independent submission atom\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_decisions\' THEN\n  SELECT * INTO STRICT sub FROM proposal_submissions WHERE tenant_id=NEW.tenant_id AND id=NEW.submission_id;\n  IF r.operation<>\'proposal.g0.decide\' OR r.actor_id<>NEW.decided_by\n   OR p.status<>NEW.outcome OR p.current_submission_id<>NEW.submission_id\n   OR p.owner_id<>NEW.owner_id OR NEW.review_digest<>sub.document_digest\n   OR NEW.decided_by<>sub.reviewer_id THEN RAISE EXCEPTION \'M3 named decision atom\'; END IF;\n  IF NEW.outcome=\'approved\' AND (\n   NOT EXISTS(SELECT 1 FROM definition_revisions def WHERE def.tenant_id=NEW.tenant_id\n    AND def.id=NEW.created_definition_id AND def.product_id=NEW.created_product_id\n    AND def.sealed AND def.revision=1 AND def.g0_decision_id=NEW.id)\n   OR NOT EXISTS(SELECT 1 FROM projects project WHERE project.tenant_id=NEW.tenant_id\n    AND project.id=NEW.created_project_id AND project.product_id=NEW.created_product_id\n    AND project.g0_decision_id=NEW.id AND project.owner_id=NEW.project_owner_id)\n   OR NOT EXISTS(SELECT 1 FROM project_product_links link WHERE link.tenant_id=NEW.tenant_id\n    AND link.project_id=NEW.created_project_id AND link.product_id=NEW.created_product_id\n    AND link.definition_id=NEW.created_definition_id AND link.definition_revision=1)\n   OR (SELECT count(*) FROM project_open_items oi WHERE oi.tenant_id=NEW.tenant_id\n    AND oi.g0_decision_id=NEW.id)<>jsonb_array_length(NEW.dispositions)) THEN\n   RAISE EXCEPTION \'M3 G0 results must commit together\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_item_versions\' THEN\n  IF r.operation=\'proposal.g0.decide\' THEN\n   SELECT * INTO STRICT d FROM proposal_decisions WHERE tenant_id=NEW.tenant_id AND receipt_id=r.id;\n   SELECT item INTO STRICT frozen FROM proposal_submissions ps,\n    LATERAL jsonb_array_elements(ps.frozen_document->\'items\') item\n    WHERE ps.tenant_id=NEW.tenant_id AND ps.id=d.submission_id AND item->>\'item_id\'=NEW.item_id::text;\n   IF d.outcome<>\'approved\' OR NEW.kind<>\'question\' OR NEW.removed\n    OR NEW.version<>(frozen->>\'version\')::int+1\n    OR NEW.content IS DISTINCT FROM ((frozen->\'content\')||\'{"status":"carried"}\'::jsonb)\n    OR NEW.origin IS DISTINCT FROM frozen->>\'origin\'\n    OR NEW.source_refs IS DISTINCT FROM frozen->\'source_refs\'\n    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d.dispositions) disp\n     WHERE disp->>\'subject_type\'=\'question\' AND disp->>\'subject_id\'=NEW.item_id::text)\n    THEN RAISE EXCEPTION \'M3 only decided questions may be carried\'; END IF;\n  END IF;\n  IF r.operation NOT IN (\'proposal.create\',\'proposal.item.patch\',\'proposal.question.create\',\'proposal.g0.decide\')\n   OR NOT coalesce((\n    (NEW.origin=\'human\' AND NEW.writer_id=r.actor_id AND NEW.run_id IS NULL\n     AND NEW.confirmed_by IS NULL AND NEW.prepared_candidate_id IS NULL AND r.agent_run_id IS NULL)\n    OR (NEW.origin=\'ai_draft\' AND NEW.writer_id=r.actor_id AND NEW.run_id=r.agent_run_id\n     AND NEW.confirmed_by IS NULL AND NEW.prepared_candidate_id IS NULL\n     AND EXISTS(SELECT 1 FROM agent_runs ar WHERE ar.tenant_id=NEW.tenant_id AND ar.id=NEW.run_id\n      AND ar.category_id=NEW.category_id AND ar.requester_id=r.requester_id AND ar.writer_id=r.actor_id\n      AND ar.proposal_id=NEW.proposal_id AND ar.reverted_at IS NULL AND ar.state<>\'cancelled\')\n     AND EXISTS(SELECT 1 FROM agent_tool_calls ac WHERE ac.tenant_id=NEW.tenant_id\n      AND ac.run_id=NEW.run_id AND ac.receipt_id=r.id AND ac.state=\'completed\'\n      AND ac.execution_binding->>\'operation\'=r.operation)\n     AND NOT EXISTS(SELECT 1 FROM proposal_item_versions prior WHERE prior.tenant_id=NEW.tenant_id\n      AND prior.item_id=NEW.item_id AND prior.version=NEW.version-1\n      AND (prior.origin=\'human\' OR prior.confirmed_by IS NOT NULL)))\n    OR (NEW.origin=\'ai_draft\' AND r.agent_run_id IS NULL AND NEW.confirmed_by=r.actor_id\n     AND EXISTS(SELECT 1 FROM proposal_prepared_candidates pc WHERE pc.tenant_id=NEW.tenant_id\n      AND pc.id=NEW.prepared_candidate_id AND pc.category_id=NEW.category_id\n      AND pc.requester_id=r.requester_id AND pc.writer_id=NEW.writer_id AND pc.run_id=NEW.run_id\n      AND pc.operation=r.operation))\n    OR (r.operation=\'proposal.g0.decide\' AND NEW.origin=\'ai_draft\'\n     AND NEW.origin=frozen->>\'origin\' AND NEW.writer_id=(frozen->>\'writer_id\')::uuid\n     AND NEW.run_id=(frozen->>\'run_id\')::uuid AND NEW.confirmed_by=r.actor_id\n     AND NEW.prepared_candidate_id IS NULL)),false)\n  THEN RAISE EXCEPTION \'M3 version provenance\'; END IF;\n ELSIF TG_TABLE_NAME=\'proposal_revisions\' THEN\n  IF NEW.actor_id<>r.actor_id OR NEW.run_id IS DISTINCT FROM r.agent_run_id\n   OR NEW.revision<>r.subject_revision THEN\n   RAISE EXCEPTION \'M3 document receipt revision\'; END IF;\n END IF;\n RETURN NULL;\nEND $function$\n', 'DROP FUNCTION m3_evidence_proposal_identity_tokens(uuid,uuid,uuid)')
